package org.telegram.messenger; import java.util.*; import java.net.*; public class AndroidUtilities { public static void runOnUIThread(Runnable r){r.run();} public static java.util.ArrayList<Runnable> polls = new java.util.ArrayList<>(); public static void runOnUIThread(Runnable r,long delay){ if (delay < 5000) polls.add(r); } public static void cancelRunOnUIThread(Runnable r){} public static SharedConfig.ProxyInfo parseProxyInfo(String link) { try {String[] terms=link.substring(link.indexOf('?')+1).split("&"); Map<String,String> p=new HashMap<>(); for(String t:terms){String[] kv=t.split("=",2);if(kv.length==2)p.put(kv[0],URLDecoder.decode(kv[1],"UTF-8"));} if(!p.containsKey("server"))return null;return new SharedConfig.ProxyInfo(p.get("server"),Integer.parseInt(p.get("port")),"","",p.getOrDefault("secret","")); } catch(Exception e){return null;} } }